'use client';

import * as React from 'react';

// @interlace/distribution v1.2.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/distribution
// What changed since: https://ds.interlace.tools/c/distribution#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — Distribution
 *
 * One quantity spread across a fixed set of bins — hours of the day, days of
 * the week, cohorts, buckets — with an optional REFERENCE distribution drawn
 * over it.
 *
 * ## Why this is not `TimeSeries` with three more props
 *
 * It was attempted that way first. Every part of `TimeSeries` is chronological
 * in a way that cannot be parameterised out:
 *
 *   - its axis keys are `day(t)`, sorted — a calendar. Bins are NAMES, and
 *     sorting `['Thu','Fri','Sat']` gives `['Fri','Sat','Thu']`, which is a
 *     week that does not exist;
 *   - a LINE asserts that the metric passed through every value between two
 *     samples. Between "readers awake at 14:00" and "readers awake at 15:00"
 *     there is nothing to pass through — the quantity is an aggregate OF the
 *     bin, not a sample at an instant;
 *   - `delta()` — first → last — is the sentence `TimeSeries` speaks, and on a
 *     cyclical axis the first and last bins are neighbours. "Down 40% from
 *     00:00 to 23:00" is arithmetic performed on a circle.
 *
 * So the marks are BARS from a zero baseline (see `bandScales` for why the
 * axis cannot be truncated), the axis order is the caller's, and the summary
 * sentence answers where the peak is rather than which way it went.
 *
 * ## The reference is the whole point, and it shares one domain
 *
 * A distribution on its own answers "when did this happen". The question worth
 * asking is almost always "when did this happen *against what was available*"
 * — reading against readers awake, incidents against traffic, deploys against
 * working hours. The gap between the bars and the reference IS the finding.
 *
 * Both series therefore share ONE y domain, exactly as in `TimeSeries`, and for
 * the same reason: two axes let an author slide one against the other until
 * they cross where the argument needs them to. That means the reference must
 * be in the SAME unit as the bars — usually both as shares of their own
 * denominator ("% of the week's reading" vs "% of readers awake"). A reference
 * in raw counts against bars in percent is not a chart this component will
 * draw honestly, and the fix is arithmetic in the caller, not a second axis.
 *
 * ## An unmeasured bin is not an empty bin
 *
 * This is where a bar chart is at its most dangerous: a bar of height zero and
 * a bar that was never drawn are the SAME PICTURE. Everywhere else in the
 * package a `null` can simply be skipped; here skipping it silently asserts a
 * zero. So an unmeasured bin gets a diagonal hatch across the full height of
 * its slot — the same mark `not-counted` carries in `DataStateBadge` and
 * `Meter` — and the accessible sentence counts them out loud.
 *
 * ## MIN_VIEWPORT — 320
 *
 * The plot is `viewBox`-scaled with no fixed width, the x labels are real HTML
 * (SVG text in this box paints at 4px at a 320 viewport — measured, not
 * reasoned about), the label row thins to its ends below `sm`, and the data
 * table scrolls inside its own box.
 *
 * ## Anatomy
 *
 *   <figure data-slot="distribution" data-min-viewport="320" data-peak-bin="14">
 *     <figcaption>{label}</figcaption>
 *     <ul data-slot="distribution-legend" />        // only with a reference
 *     <svg data-slot="distribution-plot" role="img" tabIndex={0}>
 *       <rect data-slot="distribution-gap" />       // hatched: not measured
 *       <rect data-slot="distribution-bar" />       // observed
 *       <path data-slot="distribution-reference" /> // step, never sloped
 *     </svg>
 *     <div data-slot="distribution-axis" />         // HTML labels + notes
 *     <div data-slot="distribution-readout"><output aria-live="polite" /></div>
 *     <SeriesTable axis="category" />
 *   </figure>
 *
 * | Rule | Concept                    | Where in this file                                        |
 * | ---- | -------------------------- | --------------------------------------------------------- |
 * | R6   | data-slot on every part    | `"distribution" / "-plot" / "-bar" / "-gap" / "-axis"`     |
 * | R7   | className merged + ...rest | `cn(...)` + `{...props}`                                   |
 * | R8   | No `isXxx`; enums          | `axis="category"` downstream; no boolean modes             |
 * | R10  | Composition seams          | `<SeriesTable>` renders the data; the caller owns the bins |
 * | R13  | Ecosystem first            | no charting dep — `bandScales` + SVG is the engine         |
 * | R14  | Declares min viewport      | `data-min-viewport={String(MIN_VIEWPORT)}`                 |
 * | R18  | Tailwind only              | zero inline `style`                                        |
 * | R19  | Tokens only                | `fill-chart-1`, `stroke-chart-2`, `stroke-viz-axis`        |
 * | R20  | AA contrast                | axis + hatch on `--viz-axis` (3.49:1 light / 3.83:1 dark)  |
 * | R23  | Absence is a vocabulary    | `loading` / `error` / no-bins / unmeasured-bin are four    |
 * | R25  | Client component           | pointer + key handlers, `useState`                         |
 * | R26  | A11y                       | `role="img"` + label + focusable + live readout + table    |
 */

import { cn } from '@/lib/utils';
import {
  announceDataState,
  resolveDataState,
  type AnnouncementOptions,
} from '@/components/ui/data-state';
import { Skeleton } from '@/components/ui/skeleton';
import { SeriesTable } from '@/components/ui/charts/series-table';
import {
  axisSlots,
  bandScales,
  describeDistribution,
  keepAtNarrow,
  peakBin,
  slotAt,
  stepPath,
  ticks,
  type Bin,
} from '@/components/ui/charts/scale';

export const MIN_VIEWPORT = 320 as const;

/** Internal drawing width in user units. The viewBox scales it to any container. */
const W = 900;
const PAD_LEFT = 44;
const PAD_TOP = 14;

/** `PAD_LEFT` as a percentage of `W`, so the HTML label row starts where the plot does. */
const AXIS_PAD_LEFT = 'pl-[4.889%]';

/**
 * At most eight x labels.
 *
 * `TimeSeries` caps at five because its labels are dates (`08-14`, five
 * characters, and the middles drop below `sm`). Bin labels are shorter by
 * nature — an hour, a weekday abbreviation — and eight is what lets a 24-bin
 * clock label every third bin, which is the granularity at which a reader can
 * still find "about 3pm" without counting.
 */
const MAX_LABELS = 8;

/** Share of its band a bar occupies. The rest is the gutter that separates them. */
const BAR_WIDTH = 0.7;

/** The name a reader sees. One fallback, used by the legend, readout and table alike. */
const named = (label: string | undefined, fallback: string): string => label ?? fallback;

/** One bin, plus the two things a bin can carry that a `Point` cannot. */
export interface DistributionBin extends Bin {
  /**
   * A second reading of the same slot, on ANOTHER axis family — "09:00" under
   * "14:00 UTC", "Q3" under "Jul".
   *
   * This is the honest replacement for the UTC/local toggle every clock chart
   * hand-rolls. A toggle shows one axis and hides the other, so a reader
   * comparing their own morning against a UTC peak has to hold one of the two
   * in their head; and the hidden one is missing from any screenshot of the
   * chart. Both readings are printed, and both travel into the readout and the
   * data table.
   */
  note?: string;
  /**
   * This bin's REFERENCE value, in the same unit as `v`.
   *
   * On the bin rather than in a parallel array on purpose: a
   * `reference: number[]` beside `bins` is an off-by-one waiting to happen, and
   * the failure is silent — every bar simply lines up against its neighbour's
   * reference.
   */
  reference?: number | null;
}

export interface DistributionProps
  extends Omit<React.ComponentProps<'figure'>, 'children'> {
  /**
   * The bins, in the order they belong on the axis. That order is the axis —
   * nothing here sorts them.
   */
  bins: readonly DistributionBin[];
  /** Name of the plotted quantity — used in the caption, label, readout and table. */
  label?: string;
  /** Noun for the values, e.g. "views", "%". */
  unit?: string;
  /** Name of the reference overlay. Drawn whenever any bin has a `reference`. */
  referenceLabel?: string;
  /** Column header for the bin column of the data table — "Hour", "Weekday". */
  binLabel?: string;
  /** Drawing height in user units. The rendered height follows the container width. */
  height?: number;
  /** Render the data table visibly under the chart instead of `sr-only`. */
  showTable?: boolean;
  /** Render a `<Skeleton variant="chart" />` placeholder at the chart's own height. */
  loading?: boolean;
  /**
   * The fetch failed. A different statement from "every bin is empty", which is
   * a real and interesting finding about the subject; this is a fact about the
   * request. Ranked directly under `loading`, per `DATA_STATES`.
   */
  error?: unknown;
  /** Context for the absence sentences — noun, coverage, reason. */
  announce?: AnnouncementOptions;
}

export const Distribution = React.forwardRef<HTMLElement, DistributionProps>(
  function Distribution(
    {
      bins,
      label,
      unit,
      referenceLabel,
      binLabel = 'Bin',
      height = 220,
      showTable = false,
      loading = false,
      error,
      announce,
      className,
      ...props
    },
    ref,
  ) {
    const [cursor, setCursor] = React.useState<number | null>(null);
    const svgRef = React.useRef<SVGSVGElement>(null);

    // React's generated ids contain `:`, which is legal in an id and awkward
    // everywhere else. The pattern is referenced by `url(#…)`, and one hatch
    // definition per instance is what keeps two charts on one page from
    // sharing — and then fighting over — a single `<pattern id="hatch">`.
    const hatchId = `distribution-hatch-${React.useId().replace(/[^\w-]/g, '')}`;

    const values = React.useMemo(() => bins.map((bin) => bin.v), [bins]);
    const references = React.useMemo(
      () => bins.map((bin) => bin.reference ?? null),
      [bins],
    );

    // "Is there a reference to draw" is exactly "does any bin have a measured
    // reference", which `peakBin` already answers — rather than a second
    // hand-rolled scan that could disagree with the one the axis uses.
    const hasReference = peakBin(references) !== null;

    const plot = React.useMemo(
      () => bandScales([values, references], W - PAD_LEFT, height, PAD_TOP),
      [values, references, height],
    );
    const px = React.useCallback((slot: number) => PAD_LEFT + plot.x(slot), [plot]);

    const axisTicks = React.useMemo(
      () => ticks({ points: bins, min: plot.min, max: plot.max }, 4),
      [bins, plot],
    );
    const labelSlots = React.useMemo(
      () => axisSlots(bins.length, MAX_LABELS),
      [bins.length],
    );
    const labelPosition = React.useMemo(
      () => new Map(labelSlots.map((slot, index) => [slot, index])),
      [labelSlots],
    );

    const last = bins.length - 1;
    const move = React.useCallback(
      (next: number) => setCursor(Math.max(0, Math.min(last, next))),
      [last],
    );

    const onKeyDown = (event: React.KeyboardEvent<SVGSVGElement>) => {
      const current = cursor ?? 0;
      switch (event.key) {
        case 'ArrowRight':
          move(current + 1);
          break;
        case 'ArrowLeft':
          move(current - 1);
          break;
        case 'Home':
          move(0);
          break;
        case 'End':
          move(last);
          break;
        case 'Escape':
          setCursor(null);
          return; // no preventDefault — Escape may close an enclosing overlay
        default:
          return;
      }
      // Arrow keys scroll the page by default; a focused chart owns them.
      event.preventDefault();
    };

    const onPointerMove = (event: React.PointerEvent<SVGSVGElement>) => {
      const box = svgRef.current?.getBoundingClientRect();
      if (!box || box.width === 0) return;
      const userX = ((event.clientX - box.left) / box.width) * W - PAD_LEFT;
      // The pointer lands in a BAND, not near a vertex — `slotAt`, not
      // `nearestSlot`. A bar owns its whole band, and rounding to the closest
      // centre would highlight a bin the pointer is visibly not over.
      move(slotAt(bins.length, userX, W - PAD_LEFT));
    };

    // Loading and error are resolved before every "there is nothing to draw"
    // branch, through the same function `StatStrip` and `Meter` use — data in
    // flight and data that failed to arrive are two claims, and neither is the
    // claim "this subject has no distribution".
    //
    // Every hook above runs unconditionally, so no prop can change hook order.
    const absence = resolveDataState({ loading, error }, announce);

    if (absence.state === 'loading') {
      return (
        <Skeleton
          variant="chart"
          data-slot="distribution"
          data-min-viewport={String(MIN_VIEWPORT)}
          className={className}
        />
      );
    }

    if (absence.state === 'error') {
      return (
        <figure
          ref={ref}
          data-slot="distribution-error"
          data-state="error"
          data-min-viewport={String(MIN_VIEWPORT)}
          className={cn(
            'm-0 w-full rounded-lg border border-destructive/40 p-6',
            className,
          )}
          {...props}
        >
          <p role="alert" className="text-sm text-destructive">
            {announceDataState('error', announce)} The shape of this
            distribution is unknown, not flat.
          </p>
        </figure>
      );
    }

    // No BINS at all — there is no axis to draw, which is a different thing
    // from an axis whose bins were never measured. That second case renders
    // below as a plot full of hatch, because "we looked at all 24 hours and
    // measured none of them" is a finding and an empty box is not.
    if (bins.length === 0) {
      return (
        <figure
          ref={ref}
          data-slot="distribution-empty"
          data-min-viewport={String(MIN_VIEWPORT)}
          className={cn('m-0 w-full rounded-lg border border-border p-6', className)}
          {...props}
        >
          <p className="text-sm text-muted-foreground">
            No bins to plot. A distribution needs the set of slots it is spread
            across, even when every one of them is empty.
          </p>
        </figure>
      );
    }

    const peak = peakBin(values);
    const referenceName = named(referenceLabel, 'Reference');
    const primaryName = named(label, 'Value');

    /** `label` and its second axis reading, as one string. */
    const binKey = (bin: DistributionBin): string =>
      bin.note ? `${bin.label} (${bin.note})` : bin.label;

    const spoken = (value: number | null): string =>
      value === null
        ? 'not measured'
        : `${value.toLocaleString()}${unit ? ` ${unit}` : ''}`;

    /**
     * The crosshair readout, for BOTH the pointer and the keyboard. One string,
     * built once, rendered once — the same rule `TimeSeries` follows, for the
     * same reason: a second hover-only surface can be right while the live
     * region is wrong, and only a sighted mouse user would ever find out.
     */
    const readout =
      cursor === null
        ? ''
        : [
            binKey(bins[cursor]),
            hasReference
              ? `${primaryName} ${spoken(values[cursor])}`
              : spoken(values[cursor]),
            ...(hasReference
              ? [`${referenceName} ${spoken(references[cursor])}`]
              : []),
          ].join(' · ');

    const referencePath = stepPath(references, plot);
    const tableSeries = [
      { label: primaryName, points: bins.map((bin) => ({ t: binKey(bin), v: bin.v })) },
      ...(hasReference
        ? [
            {
              label: referenceName,
              points: bins.map((bin) => ({ t: binKey(bin), v: bin.reference ?? null })),
            },
          ]
        : []),
    ];

    return (
      <figure
        ref={ref}
        data-slot="distribution"
        data-min-viewport={String(MIN_VIEWPORT)}
        data-bin-count={String(bins.length)}
        // The peak, published rather than only drawn: "where does this peak"
        // is the first question a distribution is asked, and a caller should
        // not have to re-derive it from the same array to write a sentence
        // under the chart.
        data-peak-bin={peak === null ? undefined : String(peak)}
        // `w-full` is load-bearing: the plot sizes itself from the container
        // via `viewBox`, so a figure that collapses to zero width paints
        // nothing. See the same note in time-series.tsx.
        className={cn('m-0 flex w-full flex-col gap-2', className)}
        {...props}
      >
        {label && (
          <figcaption className="text-xs text-muted-foreground">
            {label}
            <span className="sr-only">, </span>
            <span aria-hidden> · </span>
            {bins.length} bins
          </figcaption>
        )}

        {hasReference && (
          <ul
            data-slot="distribution-legend"
            className="m-0 flex list-none flex-wrap items-center gap-x-4 gap-y-1 p-0 text-xs text-muted-foreground"
          >
            <li className="flex items-center gap-1.5">
              {/* The swatch repeats the MARK, not only the hue: a filled block
                  for the bars, a dashed rule for the step. A legend of two
                  identical bars in two colours identifies nothing in
                  greyscale. */}
              <svg aria-hidden width={24} height={8} viewBox="0 0 24 8" className="shrink-0">
                <rect x={2} y={0} width={20} height={8} className="fill-chart-1" />
              </svg>
              {primaryName}
            </li>
            <li className="flex items-center gap-1.5">
              <svg aria-hidden width={24} height={8} viewBox="0 0 24 8" className="shrink-0">
                <line
                  x1={0}
                  y1={4}
                  x2={24}
                  y2={4}
                  strokeWidth={2}
                  strokeDasharray="6 4"
                  className="stroke-chart-2"
                />
              </svg>
              {referenceName}
            </li>
          </ul>
        )}

        <svg
          ref={svgRef}
          data-slot="distribution-plot"
          viewBox={`0 0 ${W} ${height}`}
          className={cn(
            'block w-full touch-pan-y rounded-md',
            'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring',
          )}
          role="img"
          aria-label={`${describeDistribution(bins, label, unit)}${
            hasReference
              ? ` ${describeDistribution(
                  bins.map((bin) => ({ label: bin.label, v: bin.reference ?? null })),
                  referenceName,
                  unit,
                )}`
              : ''
          } Focus this chart and use the left and right arrow keys to read individual bins.`}
          tabIndex={0}
          onKeyDown={onKeyDown}
          onPointerMove={onPointerMove}
          onPointerLeave={() => setCursor(null)}
          onBlur={() => setCursor(null)}
        >
          <defs>
            {/* The hatch, as SVG rather than the `HATCH_CLASS` background used
                by `DataStateBadge`: a CSS background-image does not paint on an
                SVG shape, so the vocabulary's mark has to be re-expressed in
                the medium. Same angle, same token, same meaning. */}
            <pattern
              id={hatchId}
              width={6}
              height={6}
              patternUnits="userSpaceOnUse"
              patternTransform="rotate(45)"
            >
              <line
                x1={0}
                y1={0}
                x2={0}
                y2={6}
                className="stroke-viz-axis"
                strokeWidth={1}
              />
            </pattern>
          </defs>

          {axisTicks.map((value) => {
            const y = plot.y(value);
            return (
              <g key={value}>
                <line
                  x1={PAD_LEFT}
                  y1={y}
                  x2={W}
                  y2={y}
                  className="stroke-viz-grid"
                  strokeWidth={1}
                  aria-hidden
                />
                <text
                  x={PAD_LEFT - 8}
                  y={y}
                  dominantBaseline="middle"
                  textAnchor="end"
                  className="fill-muted-foreground text-xs tabular-nums"
                  aria-hidden
                >
                  {Math.round(value).toLocaleString()}
                </text>
              </g>
            );
          })}

          <line
            x1={PAD_LEFT}
            y1={PAD_TOP}
            x2={PAD_LEFT}
            y2={plot.y(plot.min)}
            className="stroke-viz-axis"
            strokeWidth={1}
            aria-hidden
          />
          {/* The baseline is ZERO, not the bottom of the box. On a bar chart
              they are the same line only when the domain has no negatives, and
              drawing the box edge instead is how a negative bar ends up
              hanging off an axis it never crosses. */}
          <line
            data-slot="distribution-baseline"
            x1={PAD_LEFT}
            y1={plot.zero}
            x2={W}
            y2={plot.zero}
            className="stroke-viz-axis"
            strokeWidth={1}
            aria-hidden
          />

          {bins.map((bin, index) => {
            const x = px(index) + (plot.band * (1 - BAR_WIDTH)) / 2;
            const width = plot.band * BAR_WIDTH;

            // Not measured. A skipped bar and a zero bar are the same picture,
            // so the slot says which one it is instead of staying blank.
            if (bin.v === null) {
              return (
                <rect
                  key={bin.label}
                  data-slot="distribution-gap"
                  data-state="not-counted"
                  x={px(index)}
                  y={PAD_TOP}
                  width={plot.band}
                  height={Math.max(0, plot.y(plot.min) - PAD_TOP)}
                  fill={`url(#${hatchId})`}
                  aria-hidden
                />
              );
            }

            const y = plot.y(bin.v);
            return (
              <rect
                key={bin.label}
                data-slot="distribution-bar"
                x={x}
                y={Math.min(y, plot.zero)}
                width={width}
                height={Math.abs(plot.zero - y)}
                rx={2}
                className="fill-chart-1"
                aria-hidden
              />
            );
          })}

          {referencePath && (
            <path
              data-slot="distribution-reference"
              // The step lives in unshifted scale space, like the series paths
              // in time-series.tsx, so one translate covers it and everything
              // positioned with `px()` stays on the other side of that seam.
              transform={`translate(${PAD_LEFT} 0)`}
              d={referencePath}
              fill="none"
              strokeWidth={2}
              strokeLinejoin="round"
              strokeDasharray="6 4"
              className="stroke-chart-2"
              aria-hidden
            />
          )}

          {cursor !== null && (
            <rect
              data-slot="distribution-cursor"
              x={px(cursor)}
              y={PAD_TOP}
              width={plot.band}
              height={Math.max(0, plot.y(plot.min) - PAD_TOP)}
              className="fill-viz-crosshair opacity-20"
              aria-hidden
            />
          )}
        </svg>

        {/* The x scale, in HTML at a real 12px. One cell per bin — including
            the unlabelled ones — because a flex row of equal cells is the only
            way to keep a label centred under its band at every width without
            an inline style. */}
        <div
          data-slot="distribution-axis"
          aria-hidden
          className={cn(
            'flex text-xs text-muted-foreground tabular-nums',
            AXIS_PAD_LEFT,
          )}
        >
          {bins.map((bin, index) => {
            const position = labelPosition.get(index);
            return (
              <span
                key={bin.label}
                className={cn(
                  'min-w-0 flex-1',
                  // A label is wider than its cell on any dense axis — 24 bins
                  // at a 320 viewport gives each cell ~11px and "00:00" wants
                  // 30. Spilling over an EMPTY neighbouring cell is harmless;
                  // spilling outside the row is not, because it is what makes
                  // the page scroll sideways. So the two labels that can only
                  // spill outward are pinned to the edges instead — the same
                  // thing `TimeSeries` gets from `justify-between`.
                  position === 0
                    ? 'text-start'
                    : position === labelSlots.length - 1
                      ? 'text-end'
                      : 'text-center',
                )}
              >
                {position === undefined ? null : (
                  <span
                    className={
                      keepAtNarrow(position, labelSlots.length)
                        ? undefined
                        : 'hidden sm:inline'
                    }
                  >
                    {bin.label}
                    {bin.note ? (
                      // Hierarchy by WEIGHT, not by opacity.
                      //
                      // This was `opacity-70`, and opacity is the one way to
                      // de-emphasise text that no token can protect you from:
                      // `--muted-foreground` is 8.06:1 on white, and the same
                      // colour at 70% composites to #827d77 — 4.07:1, under the
                      // AA floor for 12px text. The token measured fine; the
                      // rendered pixels did not, and only axe folding the
                      // ancestor opacity into the computed value caught it.
                      //
                      // Sharper still: `bin.note` exists BECAUSE a timezone
                      // toggle hides half the truth. Printing the second
                      // reading and then dimming it below AA is the same
                      // mistake wearing a different hat.
                      <span className="block font-normal">{bin.note}</span>
                    ) : null}
                  </span>
                )}
              </span>
            );
          })}
        </div>

        <div
          data-slot="distribution-readout"
          className="flex flex-wrap items-baseline justify-between gap-x-4 text-xs text-muted-foreground tabular-nums"
        >
          <span aria-hidden>{plot.min.toLocaleString()}</span>
          <output aria-live="polite" className="font-medium text-foreground">
            {readout}
          </output>
          <span aria-hidden>{plot.max.toLocaleString()}</span>
        </div>

        {/* `axis="category"` — the bins keep the caller's order. Sorting them
            is not merely unnecessary here, it is wrong: it would make the table
            disagree with the picture directly above it about what order the
            week happens in. */}
        <SeriesTable
          axis="category"
          keyLabel={binLabel}
          series={tableSeries}
          caption={
            hasReference
              ? `${primaryName}, ${referenceName} — full data`
              : `${primaryName} — full data${unit ? ` (${unit})` : ''}`
          }
          hidden={!showTable}
        />
      </figure>
    );
  },
);

export interface Point {
  /** ISO date, or any string that sorts correctly. */
  t: string;
  v: number | null;
}

/** A mark drawn ON the series — a publish, a release, a manual action. */
export interface Annotation {
  t: string;
  label: string;
  kind?: AnnotationKind;
}

export const ANNOTATION_KINDS = ['publish', 'release', 'action'] as const;
export type AnnotationKind = (typeof ANNOTATION_KINDS)[number];

/** Direction of travel. `flat` exists so callers never have to treat 0 as "up". */
export type Direction = 'up' | 'down' | 'flat';

/** A point that survived `numeric()` — `v` is narrowed to a number. */
export type NumericPoint = { t: string; v: number };

/**
 * Drop the gaps.
 *
 * A `null` is not plottable and must not become a 0 — a day we did not measure
 * is not a day the metric was zero, and averaging over it silently invents
 * data. Callers that want interpolation must ask for it explicitly.
 */
export const numeric = (points: readonly Point[]): NumericPoint[] =>
  points.filter((p): p is NumericPoint => typeof p.v === 'number' && Number.isFinite(p.v));

/** The x/y projectors plus the observed domain, for one series in one box. */
export interface Scales {
  points: NumericPoint[];
  x: (index: number) => number;
  y: (value: number) => number;
  min: number;
  max: number;
}

/**
 * Project a series into an SVG box.
 *
 * Two edge cases are handled here rather than in every component:
 *
 *  - **A single point** has no horizontal extent, so it is centred instead of
 *    being pinned to x=0 where it reads as the start of a line that never drew.
 *  - **A flat series** has a zero span. Dividing by it yields NaN, and clamping
 *    the span to 1 would pin the line to the top edge — which looks like a
 *    metric at its maximum rather than one that never moved. It is centred.
 */
export function seriesScales(
  points: readonly Point[],
  width: number,
  height: number,
  pad = 4,
): Scales {
  const pts = numeric(points);
  const values = pts.map((p) => p.v);
  const min = values.length ? Math.min(...values) : 0;
  const max = values.length ? Math.max(...values) : 0;
  const span = max - min;
  const last = pts.length - 1;

  const x = (index: number): number => (last > 0 ? (index / last) * width : width / 2);

  const y = (value: number): number =>
    span === 0 ? height / 2 : height - pad - ((value - min) / span) * (height - pad * 2);

  return { points: pts, x, y, min, max };
}

/**
 * Several series projected into ONE box: one x axis, one y domain.
 *
 * ## Why the axis is the union of days and not "series 0 wins"
 *
 * Letting the first series own the axis is a line of code cheaper and drops
 * every reading the others took on a day the first one missed — silently, and
 * only in the picture, so the `<SeriesTable>` beside it would still list them.
 * A chart that disagrees with its own table is worse than no chart. The x axis
 * is therefore the sorted union of `day(t)` across every series, exactly the
 * key set `<SeriesTable>` builds, and a series simply has no vertex at a slot
 * it did not measure.
 *
 * ## Why there is one y domain and never two
 *
 * A second y axis lets an author slide two unrelated series until they appear
 * to cross where the argument needs them to. The domain here is the union of
 * every value, so a series that is genuinely two orders of magnitude smaller
 * *renders* as flat — which is the true statement about it. Plot it as its own
 * chart, or as a `MetricTable` row.
 */
export interface PlotScales {
  /** Sorted union of `day(t)` across every series. Slot i is `keys[i]`. */
  keys: string[];
  /** Slot index → user-unit x. */
  x: (slot: number) => number;
  /** Value → user-unit y. Shared, so two lines are on one scale. */
  y: (value: number) => number;
  min: number;
  max: number;
  /** One projector per input series, in input order, sharing the axis above. */
  series: Scales[];
  /** A series' value at a slot. `null` = that series has no reading that day. */
  at: (seriesIndex: number, slot: number) => number | null;
}

/**
 * Project several series onto one shared axis.
 *
 * Two readings on the same day collapse to the last one, which is the rule
 * `<SeriesTable>` already applies — the alternative is a chart and a table that
 * report a different number for the same date.
 */
export function plotScales(
  series: readonly (readonly Point[])[],
  width: number,
  height: number,
  pad = 4,
): PlotScales {
  const byKey = series.map((points) => new Map(numeric(points).map((p) => [day(p.t), p.v])));
  const keys = [...new Set(byKey.flatMap((m) => [...m.keys()]))].sort();
  const slotOf = new Map(keys.map((key, slot) => [key, slot]));

  const values = byKey.flatMap((m) => [...m.values()]);
  const min = values.length ? Math.min(...values) : 0;
  const max = values.length ? Math.max(...values) : 0;
  const span = max - min;
  const lastSlot = keys.length - 1;

  const x = (slot: number): number => (lastSlot > 0 ? (slot / lastSlot) * width : width / 2);
  const y = (value: number): number =>
    span === 0 ? height / 2 : height - pad - ((value - min) / span) * (height - pad * 2);

  return {
    keys,
    x,
    y,
    min,
    max,
    // Each entry is an ordinary `Scales`, so `linePath` / `areaPath` need no
    // multi-series variant: only the meaning of the index changes, and it
    // stays private to this closure.
    series: byKey.map((m) => {
      const points: NumericPoint[] = keys
        .filter((key) => m.has(key))
        .map((key) => ({ t: key, v: m.get(key)! }));
      return { points, x: (index) => x(slotOf.get(points[index].t)!), y, min, max };
    }),
    at: (seriesIndex, slot) => byKey[seriesIndex].get(keys[slot]) ?? null,
  };
}

/**
 * Which slots get a labelled tick.
 *
 * Evenly spaced and capped, because the x labels are HTML at a fixed 12px while
 * the plot they sit under is `viewBox`-scaled — at 320 the plot is 288px wide
 * and a label per observation would overlap long before the reader ran out of
 * dates. Returns fewer than `max` when the series is shorter, and never repeats
 * a slot.
 */
export function axisSlots(count: number, max = 5): number[] {
  if (count <= 0) return [];
  if (max < 2 || count === 1) return [0];
  if (count <= max) return Array.from({ length: count }, (_, i) => i);
  const last = count - 1;
  return [...new Set(Array.from({ length: max }, (_, i) => Math.round((i / (max - 1)) * last)))];
}

/**
 * Which of a set of evenly spaced labels survive below `sm`: the two ends, plus
 * the midpoint when the count is odd.
 *
 * Five five-character labels clear a 288px plot by ~12px and a longer format
 * would not — so the narrow case drops to three rather than depending on the
 * labels staying short. The ENDS are never dropped, because the ends are the
 * range; a chart whose axis has lost its last label has lost its scale.
 *
 * Lives here rather than in a component because two charts now thin the same
 * axis, and two copies of this predicate is how one of them ends up dropping an
 * end label at a width the other survives.
 */
export const keepAtNarrow = (index: number, count: number): boolean =>
  index === 0 || index === count - 1 || index === (count - 1) / 2;

/** An SVG path `d` for the series polyline. Empty string for <2 points. */
export const linePath = (scales: Scales): string =>
  scales.points.length < 2
    ? ''
    : scales.points.map((p, i) => `${i ? 'L' : 'M'}${scales.x(i)},${scales.y(p.v)}`).join('');

/** The polyline closed down to the baseline, for an area fill. */
export const areaPath = (scales: Scales, height: number): string => {
  const line = linePath(scales);
  if (!line) return '';
  return `${line}L${scales.x(scales.points.length - 1)},${height}L${scales.x(0)},${height}Z`;
};

// ── Distributions: a quantity spread over bins, not over time ───────────────

/**
 * One slot of a distribution.
 *
 * `label` is the identity as well as the name — a distribution's axis is a list
 * of NAMES (hours of the day, weekdays, cohorts), not a list of instants, so
 * there is no `t` to key it by and nothing sensible to sort it into. The order
 * the caller passes IS the axis.
 *
 * `v: null` carries the same meaning it does on a `Point`: this bin was not
 * measured. It is emphatically not a zero, and here that distinction is sharper
 * than anywhere else in the package — a bar of height zero and a bar that was
 * never drawn are the same picture, so the component has to draw something
 * else entirely.
 */
export interface Bin {
  label: string;
  v: number | null;
}

/** A band (categorical) x scale plus a zero-anchored y scale. */
export interface BandScales {
  /** Width of one bin's slot in user units. */
  band: number;
  /** Bin index → the LEFT edge of its slot. */
  x: (index: number) => number;
  /** Bin index → the CENTRE of its slot, where a per-bin mark belongs. */
  centre: (index: number) => number;
  /** Value → user-unit y. */
  y: (value: number) => number;
  /** The y of zero — where every bar starts and ends. */
  zero: number;
  min: number;
  max: number;
}

/**
 * Project one or more bin series into an SVG box, sharing ONE domain.
 *
 * ## Why this is not `seriesScales` with a different x
 *
 * The y domain. `seriesScales` fits the OBSERVED band, deliberately: a metric
 * that ran 3,412 → 3,588 gets ticks inside that band, because the movement is
 * what the reader came for and rounding out to 0–4,000 would flatten it.
 *
 * A bar cannot do that. A bar encodes its value as a LENGTH from a baseline, so
 * the reader reads the ratio between two bars — and on an axis that starts at
 * 3,412 a bar twice as long is a value 2.5% larger. Truncating a bar axis is
 * the oldest chart lie there is. So the domain here always contains zero, and
 * `zero` is published so the component draws from the baseline rather than
 * from the bottom of the box.
 *
 * A negative value therefore widens the domain downward rather than being
 * clamped — a clamp would render −40 and −4,000 as the same empty slot.
 *
 * Several series go in as several arrays for the same reason `plotScales` takes
 * several: they share the domain, so the second one cannot be quietly rescaled
 * until it crosses the first wherever the argument needs it to. The band count
 * comes from the LONGEST series, so a reference that stops short leaves its
 * remaining bins empty rather than stretching the axis.
 */
export function bandScales(
  series: readonly (readonly (number | null)[])[],
  width: number,
  height: number,
  pad = 4,
): BandScales {
  const measured = series
    .flat()
    .filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
  const min = Math.min(0, ...measured);
  const max = Math.max(0, ...measured);
  const span = max - min;
  const count = Math.max(0, ...series.map((one) => one.length));
  // An empty distribution still has to hand back a usable band rather than
  // divide by zero — the component draws nothing, but it does so at full width.
  const band = count > 0 ? width / count : width;

  // Everything measured is zero: every bar is a zero-length bar sitting on the
  // baseline, which is the honest picture. Centring it (the `seriesScales` rule
  // for a flat line) would float the baseline in mid-air.
  const y = (value: number): number =>
    span === 0
      ? height - pad
      : height - pad - ((value - min) / span) * (height - pad * 2);

  return {
    band,
    x: (index) => index * band,
    centre: (index) => index * band + band / 2,
    y,
    zero: y(0),
    min,
    max,
  };
}

/**
 * Index of the largest MEASURED bin, or `null` when nothing was measured.
 *
 * "Where is the peak" is the first question anyone asks a distribution, and
 * every hand-rolled version of this chart computed it with
 * `Math.max(1, ...values)` — which invents a denominator of 1 out of an empty
 * series and reports bin 0 as the peak of a distribution that has no peak.
 * Ties go to the earliest bin, so the answer is stable across re-renders.
 */
export function peakBin(values: readonly (number | null)[]): number | null {
  let best = -1;
  for (let index = 0; index < values.length; index += 1) {
    const value = values[index];
    if (typeof value !== 'number' || !Number.isFinite(value)) continue;
    if (best === -1 || value > (values[best] as number)) best = index;
  }
  return best === -1 ? null : best;
}

/**
 * A STEP path across bins — flat over each band, never sloped between them.
 *
 * A polyline through bin centres draws a diagonal between two bins and that
 * diagonal is a claim: that the quantity passed through every value in between,
 * somewhere in between. For a per-bin aggregate ("readers awake at 14:00")
 * nothing exists between the bins to pass through. The step says the same
 * numbers without the invented interpolation.
 *
 * An unmeasured bin BREAKS the path rather than bridging it, for the reason
 * `numeric()` drops nulls: a bridge over a gap is a drawn value nobody measured.
 */
export function stepPath(
  values: readonly (number | null)[],
  scales: BandScales,
): string {
  let d = '';
  let open = false;
  for (let index = 0; index < values.length; index += 1) {
    const value = values[index];
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      open = false;
      continue;
    }
    const y = scales.y(value);
    const left = scales.x(index);
    d += `${open ? 'L' : 'M'}${left},${y}L${left + scales.band},${y}`;
    open = true;
  }
  return d;
}

/**
 * The accessible name for a distribution.
 *
 * `describeSeries` answers "where did it go"; a distribution has nowhere to go,
 * so the sentence answers the questions it can actually be asked: how much in
 * total, where the peak is, and how much of the axis was never measured. That
 * last clause is not decoration — a distribution with six unmeasured bins looks
 * exactly like one with six empty bins, and only the sentence can tell them
 * apart for a reader who is not looking at it.
 */
export function describeDistribution(
  bins: readonly Bin[],
  label?: string,
  unit?: string,
): string {
  const name = label ?? 'Distribution';
  const measured = bins.filter(
    (bin): bin is Bin & { v: number } =>
      typeof bin.v === 'number' && Number.isFinite(bin.v),
  );
  if (measured.length === 0) return `${name}: no data`;

  const peak = peakBin(bins.map((bin) => bin.v))!;
  const total = measured.reduce((sum, bin) => sum + bin.v, 0);
  const noun = unit ? ` ${unit}` : '';
  const gaps = bins.length - measured.length;

  return (
    `${name}: ${bins.length} bins, ${total.toLocaleString()}${noun} in total, ` +
    `highest in ${bins[peak].label} at ${(bins[peak].v as number).toLocaleString()}${noun}` +
    `${gaps === 0 ? '' : `, ${gaps} bin${gaps === 1 ? '' : 's'} not measured`}.`
  );
}

/** First → last change, in absolute and percentage terms. */
export interface DeltaResult {
  from: number;
  to: number;
  abs: number;
  /** `null` when the baseline is 0 — a percentage change from nothing is undefined, not infinite. */
  pct: number | null;
  direction: Direction;
}

export function delta(points: readonly Point[]): DeltaResult | null {
  const pts = numeric(points);
  if (pts.length < 2) return null;
  const from = pts[0].v;
  const to = pts[pts.length - 1].v;
  const abs = to - from;
  return {
    from,
    to,
    abs,
    pct: from === 0 ? null : (abs / Math.abs(from)) * 100,
    direction: abs > 0 ? 'up' : abs < 0 ? 'down' : 'flat',
  };
}

/** ISO timestamp → `YYYY-MM-DD`. Charts key annotations by day, not by instant. */
export const day = (t: string): string => t.slice(0, 10);

/**
 * The accessible name for a series.
 *
 * Axe cannot read an SVG, and a screen reader handed `role="img"` with no label
 * announces "image". This is the sentence that replaces the picture — every
 * chart in this package owes one, alongside its `<SeriesTable>`.
 */
export function describeSeries(points: readonly Point[], label?: string): string {
  const pts = numeric(points);
  const name = label ?? 'Series';
  if (pts.length === 0) return `${name}: no data`;
  if (pts.length === 1) return `${name}: a single value, ${pts[0].v}, on ${day(pts[0].t)}`;
  const d = delta(pts)!;
  const move =
    d.direction === 'flat'
      ? 'unchanged'
      : `${d.direction} ${Math.abs(d.abs).toLocaleString()}${
          d.pct === null ? '' : ` (${Math.abs(d.pct).toFixed(1)}%)`
        }`;
  return (
    `${name}: ${pts.length} points from ${day(pts[0].t)} to ${day(pts[pts.length - 1].t)}, ` +
    `${d.from.toLocaleString()} to ${d.to.toLocaleString()}, ${move}. ` +
    `Range ${Math.min(...pts.map((p) => p.v)).toLocaleString()} to ` +
    `${Math.max(...pts.map((p) => p.v)).toLocaleString()}.`
  );
}

/**
 * Anything carrying an observed domain plus something to count.
 *
 * `Scales` satisfies it directly; a multi-series plot passes its slot keys.
 * Widening the parameter rather than adding a `multiTicks` is deliberate — two
 * tick functions is how one chart ends up with two disagreeing y axes.
 */
export interface TickSource {
  readonly points: readonly unknown[];
  readonly min: number;
  readonly max: number;
}

/**
 * Evenly spaced axis values across the observed domain.
 *
 * Deliberately NOT "nice" rounded ticks. A metric that ran 3,412 → 3,588 gets
 * ticks inside that band; rounding out to 0–4,000 would flatten the only thing
 * the reader came for. The axis labels the data, not a textbook scale.
 */
export function ticks(scales: TickSource, count = 3): number[] {
  if (count < 2 || scales.points.length === 0) return [];
  if (scales.min === scales.max) return [scales.min];
  const step = (scales.max - scales.min) / (count - 1);
  return Array.from({ length: count }, (_, i) => scales.min + step * i);
}

/**
 * Slot nearest an x position, in SVG user units.
 *
 * The arithmetic behind every crosshair in this package. It takes a count
 * rather than a series because with two series plotted there is no single
 * series whose indices *are* the axis — the axis is the shared slot list. The
 * pointer path and the arrow-key path both land here, which is the property
 * that stops a mouse user and a keyboard user being told different things.
 */
export function nearestSlot(count: number, xPosition: number, width: number): number {
  const last = count - 1;
  if (last <= 0) return 0;
  const ratio = width === 0 ? 0 : xPosition / width;
  return Math.max(0, Math.min(last, Math.round(ratio * last)));
}

/**
 * The band an x position falls INSIDE, in SVG user units.
 *
 * `nearestSlot` rounds to the closest vertex, which is right for a line: the
 * value lives AT the vertex and the space between two of them belongs to
 * whichever is nearer. A bar owns its whole band, so the right answer is
 * containment, not proximity — rounding would hand the right-hand third of
 * every bar to its neighbour, and the reader would watch the highlight jump to
 * a bin their pointer is visibly not over.
 */
export function slotAt(count: number, xPosition: number, width: number): number {
  const last = count - 1;
  if (last <= 0) return 0;
  const ratio = width === 0 ? 0 : xPosition / width;
  return Math.max(0, Math.min(last, Math.floor(ratio * count)));
}

/**
 * Index of the point nearest an x position, for a single series.
 *
 * The one-series spelling of `nearestSlot`, kept because it is the published
 * shape of this module and delegating is what guarantees the two cannot drift
 * into rounding a boundary differently.
 */
export function nearestIndex(scales: Scales, xPosition: number, width: number): number {
  return nearestSlot(scales.points.length, xPosition, width);
}

// ── The dial: time wrapped around an arc, for the radial (poster) form ──────

/**
 * Geometry of a dial plot. The sweep is deliberately LESS than 360°: a
 * closed circle claims the last observation meets the first — that August
 * touches last December — and the gap is the honest statement that time
 * does not wrap. The gap sits at the bottom (the speedometer convention,
 * the most-practised radial read there is): time starts bottom-left and
 * proceeds clockwise over the top.
 */
export interface DialGeometry {
  cx: number;
  cy: number;
  /** Radius where `min` sits — the centre hole keeps the middle legible. */
  inner: number;
  /** Radius where `max` sits. */
  outer: number;
  /** Degrees, SVG convention (0° = +x, clockwise positive). */
  startAngle: number;
  /** Degrees of arc the time axis occupies. */
  sweep: number;
}

/** Slot → degrees. A single-slot axis sits mid-sweep, not at the start. */
export function dialAngle(slot: number, count: number, geometry: DialGeometry): number {
  return (
    geometry.startAngle +
    (count > 1 ? (slot / (count - 1)) * geometry.sweep : geometry.sweep / 2)
  );
}

/** Value → radius. A zero span centres between the rings (`seriesScales`' rule). */
export function dialRadius(
  value: number,
  min: number,
  max: number,
  geometry: DialGeometry,
): number {
  const span = max - min;
  return span === 0
    ? (geometry.inner + geometry.outer) / 2
    : geometry.inner + ((value - min) / span) * (geometry.outer - geometry.inner);
}

/** Degrees + radius → cartesian, around the dial's centre. */
export function dialPoint(
  angleDeg: number,
  radius: number,
  geometry: DialGeometry,
): { x: number; y: number } {
  const rad = (angleDeg * Math.PI) / 180;
  return { x: geometry.cx + radius * Math.cos(rad), y: geometry.cy + radius * Math.sin(rad) };
}

/**
 * A series wrapped around the dial. Straight segments between observed
 * slots — a curve through polar space would smooth in values nobody
 * measured — and a `null` BREAKS the path (`numeric()`'s rule): an arc
 * bridging a gap is a drawn value with no observation under it.
 */
export function dialPath(
  values: readonly (number | null)[],
  min: number,
  max: number,
  geometry: DialGeometry,
): string {
  let d = '';
  let open = false;
  for (let slot = 0; slot < values.length; slot += 1) {
    const value = values[slot];
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      open = false;
      continue;
    }
    const point = dialPoint(
      dialAngle(slot, values.length, geometry),
      dialRadius(value, min, max, geometry),
      geometry,
    );
    d += `${open ? 'L' : 'M'}${point.x.toFixed(2)},${point.y.toFixed(2)}`;
    open = true;
  }
  return d;
}

/**
 * A grid ring: one constant-radius arc across the whole sweep. Two `A`
 * segments rather than one: a sweep beyond 180° needs `large-arc-flag=1`
 * (and exactly 180° is ambiguous between the two semi-circles), so
 * splitting at the midpoint keeps every segment unambiguously minor —
 * correct for any sweep up to 360° without a case split.
 */
export function dialRing(radius: number, geometry: DialGeometry): string {
  const start = dialPoint(geometry.startAngle, radius, geometry);
  const mid = dialPoint(geometry.startAngle + geometry.sweep / 2, radius, geometry);
  const end = dialPoint(geometry.startAngle + geometry.sweep, radius, geometry);
  const arc = (to: { x: number; y: number }): string =>
    `A${radius},${radius} 0 0 1 ${to.x.toFixed(2)},${to.y.toFixed(2)}`;
  return `M${start.x.toFixed(2)},${start.y.toFixed(2)}${arc(mid)}${arc(end)}`;
}

/** Compact number formatting for dense rows — 12.4k, 3.1M. */
export function compact(value: number): string {
  const abs = Math.abs(value);
  if (abs >= 1e9) return `${(value / 1e9).toFixed(1)}B`;
  if (abs >= 1e6) return `${(value / 1e6).toFixed(1)}M`;
  if (abs >= 1e3) return `${(value / 1e3).toFixed(1)}k`;
  return value.toLocaleString();
}

/**
 * @interlace/ui — chart scales and series math
 *
 * Every number a chart draws comes from here. Nothing in this file imports
 * React, touches the DOM, or renders anything — which is the point: it is the
 * part of a visualisation that can be *proved* correct, so it carries the
 * 100/100/100/100 coverage gate while the SVG above it is checked by stories
 * and axe.
 *
 * There is no charting dependency, and that is a decision rather than an
 * omission. A shadcn-registry item must install from a bare `npx shadcn add`
 * with every import resolvable, and d3/recharts/visx each want to own layout.
 * The named exit: if one surface ever needs >5k points with a live crosshair,
 * *that component* goes to canvas — it does not drag a library into the other
 * twenty. See VISUALIZATION_PHILOSOPHY.md.
 */

/** One observation. `v: null` is a real gap in the data, not a zero. */
